/**
 * Nothing in the captions library throws, whatever it is handed: documents
 * are hand-written, generated by a model, or come from an older version,
 * and a caption must never take a frame down with it.
 */
import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { createCanvas, registerFonts } from '../../src/api/compose/index.js';
import * as captions from '../../src/utils/captions/index.js';

const JUNK = [undefined, null, 0, NaN, 'x', [], {}, [[]], [null], { words: 3 }, () => 1];
JUNK.push([[1, 2, 'ok'], 'bad', [NaN, NaN, {}]], [[1e308, -1e308, 'big']], new Map());
JUNK.push([[1, 2, 'a'.repeat(100000)]], Symbol.iterator, { tracks: [{ clips: 5 }, 7, null] });

describe('the captions library handed junk', () => {
  it('never throws', () => {
    registerFonts();
    const ctx = createCanvas(320, 180).getContext('2d');
    const frame = { width: 320, height: 180 };
    for (const a of JUNK) {
      for (const b of JUNK) {
        assert.doesNotThrow(
          () => {
            captions.captionAt(a, b);
            captions.captionAt(captions.captionGroups(a, b), 1.5);
            captions.repairWords(a);
            captions.normalizeCaptions(a);
            captions.wordsFromTranscript(a);
            captions.normalizeCaptionStyle(a);
            captions.flatCaptionStyle(a);
            captions.drawCaptionAt(ctx, a, 1.5, b, frame);
            captions.drawCaptionAt(ctx, a, b, a, b, 1);
            captions.layoutCaption(a, b, a, frame, () => 10);
            captions.drawCaption(ctx, null, a);
            captions.voicesAt(a, 1);
            captions.timelineCues(a, b);
            captions.timelineCues({ tracks: a, captions: b }, () => a, { group: b });
            captions.formatSrt(a);
            captions.formatVtt(a);
            captions.formatTimestamp(a);
            captions.captionFont(a, b);
            captions.captionFontNeed(a, b);
          },
          `${String(a).slice(0, 24)} with ${String(b).slice(0, 24)}`,
        );
      }
    }
  });

  it('draws on, whatever the canvas is said to be', () => {
    const ctx = createCanvas(320, 180).getContext('2d');
    const words = [[1, 2, 'hello']];
    const frames = [null, {}, { width: -1, height: 5 }, { width: 1e7, height: 1 }];
    frames.push({ width: 100, height: 100, scale: 0, outWidth: 0, outHeight: NaN });
    for (const frame of frames) {
      assert.doesNotThrow(() => captions.drawCaptionAt(ctx, words, 1.5, 'pop', frame));
      const [group] = captions.captionGroups(words, 'pop');
      assert.doesNotThrow(() => captions.layoutCaption(group, null, 'pop', frame, () => 10));
    }
    assert.equal(captions.drawCaptionAt(ctx, words, 1.5, 'pop', null), false);
  });

  it('finds no voice, and writes no cue, in a document that is not one', () => {
    const edl = {
      tracks: [
        { type: 'audio', clips: [{ clipId: 'a', captions: { on: true, words: 'x' } }, null, 5] },
        { type: 'audio', clips: [{ captions: { on: true }, linkedClipId: {} }] },
        { clips: 'nope' },
        7,
      ],
    };
    assert.equal(captions.captionVoices(edl).length, 2);
    assert.deepEqual(
      captions.timelineCues(edl, () => [[1, 2, 'hi']]),
      [],
    );
  });
});
